package com.ruoyi.medical.persistence;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import com.fasterxml.jackson.databind.node.ObjectNode;import com.ruoyi.medical.contracts.*;import java.util.*;import java.nio.charset.StandardCharsets;import java.math.BigInteger;
/** Actual bounded raw-SSE verifier; mTLS outcome admission is a separate mocked boundary here. */
class FormalProviderCaptureEvidenceTest {
 FormalInvocationSchema schema;FormalProviderCaptureEvidence verifier;FormalInvocationOutcomeAuthority.VerifiedOutcome outcome;ObjectNode artifact,result,metadata;String body;String invocation=id(1),attempt=id(2),receipt=id(3),requestHash="a".repeat(64);
 @BeforeEach void setup()throws Exception{schema=new FormalInvocationSchema();verifier=new FormalProviderCaptureEvidence(schema,16384,8192);outcome=mock(FormalInvocationOutcomeAuthority.VerifiedOutcome.class);when(outcome.invocationId()).thenReturn(invocation);when(outcome.attemptId()).thenReturn(attempt);when(outcome.binding()).thenReturn(schema.parse("{\"actual_send_manifest\":{\"provider_body\":{\"model\":\"deepseek-chat\"},\"canonical_provider_body_sha256\":\""+requestHash+"\"}}"));
  result=(ObjectNode)schema.parse("{\"provider_request_id\":\"response-fixture\",\"reason\":{\"kind\":\"stop\",\"failure\":null},\"usage\":{\"uncached_input_tokens\":3,\"cache_read_tokens\":2,\"cache_write_tokens\":null,\"output_tokens\":4,\"total_tokens\":9,\"reasoning_tokens\":null,\"source_receipt_id\":\""+receipt+"\"}}");result.putArray("blocks").addObject().put("type","text").put("text","真实字节");when(outcome.result()).thenAnswer(x->result.deepCopy());
  body="data: {\"id\":\"response-fixture\",\"model\":\"deepseek-chat\",\"choices\":[{\"index\":0,\"delta\":{\"content\":\"真实字节\"},\"finish_reason\":\"stop\"}]}\n\ndata: {\"id\":\"response-fixture\",\"model\":\"deepseek-chat\",\"choices\":[],\"usage\":{\"prompt_tokens\":5,\"completion_tokens\":4,\"total_tokens\":9,\"prompt_cache_hit_tokens\":2,\"prompt_cache_miss_tokens\":3}}\n\ndata: [DONE]\n\n";
  artifact=(ObjectNode)schema.parse("{\"schema_version\":\"1.0.0\",\"media_type\":\"application/octet-stream\",\"encoding\":\"base64\",\"metadata\":{},\"body_base64\":\"\"}");metadata=(ObjectNode)artifact.required("metadata");metadata.put("schema_version","1.0.0").put("profile","PROVIDER_HTTP_RESPONSE_ENTITY").put("invocation_id",invocation).put("dispatch_attempt_id",attempt).put("receipt_id",receipt).put("canonical_request_body_sha256",requestHash).put("request_body_sha256","b".repeat(64)).put("provider_request_id","http-header-request-fixture").put("request_id_source","HTTP_X_REQUEST_ID").put("http_status",200).put("transport_terminal","COMPLETE_EOF").put("capture_complete",true).put("provider_finish_reason","stop").put("provider_response_id","response-fixture").put("response_model","deepseek-chat").put("response_eof_observed",true).put("content_policy_status","VERIFIED_NO_INTERNAL_REASONING");body(body);
 }
 void body(String value)throws Exception{byte[] raw=value.getBytes(StandardCharsets.UTF_8);artifact.put("body_base64",Base64.getEncoder().encodeToString(raw));metadata.put("sha256",WireValues.sha256(raw)).put("size_bytes",Integer.toString(raw.length)).put("observed_bytes",Integer.toString(raw.length));}
 FormalProviderCaptureEvidence.Verified verify()throws Exception{return verifier.require(outcome,ContentReadAuthorization.canonicalBytes(artifact));}
 @Test void originalBytesAndDistinctHttpAndSdkIdsVerify()throws Exception{var proof=verify();assertTrue(proof.providerTerminal());assertEquals(BigInteger.ONE,proof.confirmedCalls());assertEquals(BigInteger.valueOf(9),proof.usage().reportedTotalTokens());assertNull(proof.usage().cacheWriteTokens());assertEquals(receipt,proof.receiptId());}
 @Test void forgedNormalizedUsageIsRejected(){((ObjectNode)result.required("usage")).put("total_tokens",99);assertThrows(TenantAccessException.class,this::verify);}
 @Test void responseModelMustMatchApprovedActualSend()throws Exception{body(body.replace("deepseek-chat","other-model"));metadata.put("response_model","other-model");assertThrows(TenantAccessException.class,this::verify);}
 @Test void rawHashTamperIsRejected(){metadata.put("sha256","c".repeat(64));assertThrows(TenantAccessException.class,this::verify);}
 @Test void hiddenInternalReasoningIsNeverAccepted()throws Exception{body(body.replace("\"content\":\"真实字节\"","\"content\":\"真实字节\",\"reasoning_content\":\"private reasoning fixture\""));assertThrows(TenantAccessException.class,this::verify);}
 @Test void incompleteCaptureDoesNotSettleEvenWhenDescriptorClaimsFinish()throws Exception{result.putArray("blocks");result.putNull("usage");((ObjectNode)result.required("reason")).put("kind","error");body("");metadata.put("capture_complete",false).put("transport_terminal","TRANSPORT_ERROR").put("content_policy_status","INCOMPLETE_RESPONSE");var proof=verify();assertFalse(proof.providerTerminal());assertNull(proof.confirmedCalls());assertNull(proof.usage().reportedTotalTokens());}
 @Test void wrongOriginalAttemptIsRejected(){metadata.put("dispatch_attempt_id",id(9));assertThrows(TenantAccessException.class,this::verify);}
 @Test void eofIsNotSuccessfulProviderCompletion()throws Exception{result.putArray("blocks");result.putNull("usage");((ObjectNode)result.required("reason")).put("kind","error");metadata.put("http_status",401).putNull("provider_finish_reason").putNull("provider_response_id").putNull("response_model");body("{\"error\":{\"code\":\"auth_failure_fixture\"}}");var proof=verify();assertFalse(proof.providerTerminal());assertNull(proof.confirmedCalls());}
 static String id(int n){return "00000000-0000-4000-8000-"+String.format("%012d",n);}
}
